INSERT INTO companies (id,name,slug,tagline,description,industry,location,employee_scale,founded_year,homepage_url,benefits) VALUES
('00000000-0000-4000-8000-000000000001','알파웍스','alpha-works','채용 담당자의 하루를 줄이는 HR 소프트웨어','알파웍스는 중견·중소기업을 위한 채용 관리 소프트웨어를 만듭니다. 공고 등록부터 지원자 심사, 합격 통보까지 한 화면에서 처리하도록 돕고, 현재 600여 개 고객사가 사용하고 있습니다.','HR SaaS','서울 성동구','120명',2018,'https://alpha-works.example',ARRAY['주 2회 재택근무','점심 식대 월 20만 원','업무 장비 선택 지원','연 150만 원 교육비','건강검진 연 1회']::text[]),
('00000000-0000-4000-8000-000000000002','베타스튜디오','beta-studio','브랜드와 제품 경험을 함께 설계하는 디자인 스튜디오','베타스튜디오는 브랜드 아이덴티티와 디지털 제품 디자인을 함께 다루는 스튜디오입니다. 금융, 커머스, 공공 분야 고객과 장기 프로젝트를 주로 진행합니다.','디자인 에이전시','서울 마포구','38명',2015,'https://beta-studio.example',ARRAY['시차 출퇴근제','프로젝트 종료 후 리프레시 휴가','디자인 도서·폰트 구입 지원','야근 시 택시비 지원']::text[]),
('00000000-0000-4000-8000-000000000003','감마로직스','gamma-logics','당일 배송을 가능하게 하는 풀필먼트 네트워크','감마로직스는 수도권 7개 풀필먼트 센터와 자체 배차 시스템으로 온라인 판매자의 입고, 보관, 출고를 대행합니다. 하루 평균 9만 건의 주문을 처리합니다.','물류 플랫폼','경기 성남시 분당구','260명',2016,'https://gamma-logics.example',ARRAY['사내 카페·구내식당 무료','통근 셔틀 운영','자녀 학자금 지원','분기별 성과급','단체 상해보험']::text[]),
('00000000-0000-4000-8000-000000000004','델타커머스','delta-commerce','취향을 발견하는 라이프스타일 쇼핑','델타커머스는 리빙·패션 편집숍 앱을 운영합니다. 월 280만 명이 방문하며, 입점 브랜드 4,200곳과 함께 성장하고 있습니다.','이커머스','서울 강남구','430명',2013,'https://delta-commerce.example',ARRAY['자사몰 포인트 연 120만 원','선택적 근로시간제','점심·저녁 식대 지원','사내 동호회 지원','장기근속 포상 휴가']::text[]),
('00000000-0000-4000-8000-000000000005','엡실론헬스','epsilon-health','만성질환 관리를 일상으로 가져옵니다','엡실론헬스는 당뇨·고혈압 환자를 위한 생활습관 코칭 앱과 병원 연동 대시보드를 제공합니다. 전국 90여 개 의원과 협력하고 있습니다.','디지털 헬스케어','대전 유성구','74명',2020,'https://epsilon-health.example',ARRAY['전 직원 스톡옵션','주 4.5일 근무','본인·가족 의료비 지원','이주 정착금 지원']::text[]),
('00000000-0000-4000-8000-000000000006','제타모빌리티','zeta-mobility','도시의 짧은 이동을 다시 설계합니다','제타모빌리티는 부산·울산·경남 지역에서 공유 전기자전거와 수요응답형 버스를 운영합니다. 지자체와 함께 교통 취약 지역의 이동 문제를 풉니다.','모빌리티','부산 해운대구','150명',2019,'https://zeta-mobility.example',ARRAY['서비스 무제한 이용권','유연근무제','기숙사 제공(신입 1년)','명절 선물·경조사 지원']::text[])
INSERT INTO job_posts (company_id,slug,title,description,work_type,department,location,career_level,salary_range,headcount,responsibilities,requirements,preferred,hiring_process,tags,closes_at,published_at) VALUES
('00000000-0000-4000-8000-000000000001','support-engineer','고객지원 엔지니어','고객 문의 해결과 지원 품질 개선을 함께합니다.','정규직','고객성공팀','서울 성동구','경력 2년 이상','4,200만 ~ 5,500만 원',2,ARRAY['고객사 기술 문의 접수와 원인 분석, 해결 안내','반복 문의를 줄이는 도움말 문서와 내부 진단 도구 개선','장애 발생 시 고객 공지와 개발팀 간 상황 전달']::text[],ARRAY['B2B 소프트웨어 기술 지원 경력 2년 이상','SQL로 데이터를 조회하고 로그를 읽어 원인을 좁힐 수 있는 분','고객에게 기술 내용을 쉬운 말로 설명할 수 있는 분']::text[],ARRAY['HR 또는 채용 도메인 경험','REST API 연동 지원 경험']::text[],ARRAY['서류 검토','1차 실무 면접','2차 문화 면접','처우 협의','최종 합격']::text[],ARRAY['SQL','Zendesk','API']::text[],date_trunc('day', now()) + interval '21 days' + interval '14 hours 59 minutes',now() - interval '9 days'),
('00000000-0000-4000-8000-000000000001','backend-engineer','백엔드 엔지니어','채용지원 서비스의 안정적인 기반을 만듭니다.','정규직','플랫폼개발팀','서울 성동구','경력 3년 이상','6,000만 ~ 8,500만 원',3,ARRAY['지원서 접수·심사 API 설계와 운영','멀티테넌트 데이터 격리와 권한 모델 개선','배포 파이프라인과 관측 지표 관리']::text[],ARRAY['서버 개발 경력 3년 이상','관계형 데이터베이스 설계와 쿼리 튜닝 경험','코드 리뷰와 테스트 작성이 습관인 분']::text[],ARRAY['개인정보를 다루는 서비스 운영 경험','AWS ECS, RDS 운영 경험']::text[],ARRAY['서류 검토','사전 과제','실무 면접','임원 면접','최종 합격']::text[],ARRAY['TypeScript','PostgreSQL','AWS']::text[],date_trunc('day', now()) + interval '30 days' + interval '14 hours 59 minutes',now() - interval '4 days'),
('00000000-0000-4000-8000-000000000001','security-engineer','보안 엔지니어','고객사의 지원자 정보를 지키는 보안 체계를 운영합니다.','정규직','보안팀','서울 성동구','경력 5년 이상','7,000만 ~ 1억 원',1,ARRAY['클라우드 인프라 보안 설정 점검과 취약점 조치 관리','접근 권한 검토와 로그 모니터링 체계 운영','ISMS-P 인증 유지와 내부 감사 대응']::text[],ARRAY['정보보호 실무 경력 5년 이상','AWS 보안 서비스 운영 경험','취약점 진단 결과를 개발팀과 조율해 조치한 경험']::text[],ARRAY['ISMS-P 인증 심사 대응 경험','정보보안기사 등 관련 자격']::text[],ARRAY['서류 검토','1차 실무 면접','2차 문화 면접','처우 협의','최종 합격']::text[],ARRAY['ISMS-P','AWS','취약점 관리']::text[],date_trunc('day', now()) + interval '14 days' + interval '14 hours 59 minutes',now() - interval '2 days'),
('00000000-0000-4000-8000-000000000001','hr-product-manager','프로덕트 매니저','채용 담당자의 심사 흐름을 책임지는 제품 로드맵을 이끕니다.','정규직','프로덕트팀','서울 성동구','경력 4년 이상','6,500만 ~ 9,000만 원',1,ARRAY['고객 인터뷰와 사용 데이터로 문제 정의','분기 로드맵 수립과 우선순위 결정','디자인·개발팀과 함께 기능 출시와 성과 측정']::text[],ARRAY['B2B 제품 기획 경력 4년 이상','가설을 세우고 지표로 검증한 경험','여러 직군과 문서로 소통하는 데 익숙한 분']::text[],ARRAY['HR 테크 또는 ATS 제품 경험']::text[],ARRAY['서류 검토','1차 실무 면접','2차 문화 면접','처우 협의','최종 합격']::text[],ARRAY['B2B SaaS','데이터 분석']::text[],NULL,now() - interval '16 days')
